/**
 * BackendProvider (design §3.3, ADR-004): one interface for both hosting modes.
 * The factory (worker, API) never talks to Supabase or the Saudi cell directly;
 * the generated app only ever sees an api_url and a publishable key.
 *
 * Provisioning is split into resumable steps (create → isReady → configure) so a
 * job that crashes or waits can pick up where it stopped.
 */

export type HostingMode = "standard" | "saudi";

export interface CreateBackendInput {
  /** Stable, human-readable name, e.g. app-flower-shop */
  name: string;
  /** Generated by the factory and stored in Vault before create is called. */
  dbPassword: string;
  /** Provider-specific placement hint (Supabase smart region group; ignored by the cell). */
  region: string | null;
  instanceSize: string | null;
}

export interface CreatedBackend {
  /** Supabase project ref, or the app id inside the Saudi cell. */
  ref: string;
  apiUrl: string;
}

export interface ConfigureBackendInput {
  siteUrl: string;
  redirectUrls: string[];
}

export interface BackendKeys {
  /** Ships inside the app bundle. */
  publishable: string;
  /** Server-side only: stored in Vault, never returned to a browser. */
  secret: string;
}

export interface BackendProvider {
  readonly mode: HostingMode;
  create(input: CreateBackendInput): Promise<CreatedBackend>;
  isReady(ref: string): Promise<boolean>;
  /** Keys and auth redirect URLs. Idempotent. */
  configure(ref: string, input: ConfigureBackendInput): Promise<BackendKeys>;
  applyMigration(ref: string, name: string, sql: string): Promise<void>;
  /** A platform-owned server function from the app's snapshot (supabase/functions/<name>/index.ts). */
  deployFunction(ref: string, name: string, source: string, opts: { verifyJwt: boolean }): Promise<void>;
  /** Blocking findings of the provider's security check (e.g. a table without RLS). */
  securityErrors(ref: string): Promise<string[]>;
  /** Secret for the app's own server functions, e.g. its owner's Moyasar key (FR-014). */
  setSecret(ref: string, name: string, value: string): Promise<void>;
  suspend(ref: string): Promise<void>;
  resume(ref: string): Promise<void>;
  destroy(ref: string): Promise<void>;
  /** Aggregate numbers only, for the admin panel (FR-013). Never rows of end-user data. */
  stats(ref: string): Promise<BackendStats>;
}

export interface BackendStats {
  dbSizeBytes: number;
  storageBytes: number;
  /** Distinct users who signed in during the last 30 days. */
  monthlyActiveUsers: number;
  /** Requests in the last 24 hours, where the provider reports them. */
  requests24h: number | null;
}

/** Thrown when a mode exists in the data model but its provider is not available yet. */
export class ProviderUnavailableError extends Error {}

/** Allowed names for app secrets: upper snake case, not reserved by Supabase. */
export function assertSecretName(name: string) {
  if (!/^[A-Z][A-Z0-9_]{1,63}$/.test(name) || name.startsWith("SUPABASE_")) {
    throw new Error(`invalid secret name: ${name}`);
  }
}

/** True once the CELL_* settings exist (the cell itself is set up by operations, ADR-002). */
export function saudiCellConfigured(e: { CELL_CONTROL_URL?: string; CELL_CLIENT_CERT?: string; CELL_CLIENT_KEY?: string }): boolean {
  return !!(e.CELL_CONTROL_URL && e.CELL_CLIENT_CERT && e.CELL_CLIENT_KEY);
}
